using OCRS.Models.Enums; using System.ComponentModel.DataAnnotations;
namespace OCRS.Models;
public class CourseClass { public int ClassId { get; set; } [Required,StringLength(20)] public string ClassCode { get; set; } = ""; [Required,StringLength(160)] public string ClassName { get; set; } = ""; public int CourseId { get; set; } public Course Course { get; set; } = null!; public int? InstructorId { get; set; } public Instructor? Instructor { get; set; } [DataType(DataType.Date)] public DateTime StartDate { get; set; } [DataType(DataType.Date)] public DateTime EndDate { get; set; } public DateTime RegistrationOpenAt { get; set; } public DateTime RegistrationCloseAt { get; set; } [Range(1,1000)] public int MaxCapacity { get; set; } public int CurrentEnrollment { get; set; } public LearningMode LearningMode { get; set; } [StringLength(250)] public string? Location { get; set; } [Url,StringLength(500)] public string? MeetingLink { get; set; } public ClassStatus Status { get; set; } = ClassStatus.Draft; public bool RequiresApproval { get; set; } public byte[] RowVersion { get; set; } = []; public ICollection<ClassSchedule> Schedules { get; set; } = []; public ICollection<Enrollment> Enrollments { get; set; } = []; }
